\begin{equation}
 \mathcal A(\rho_i,\rho_k)\mathcal A(y_i,y_k)
 =B(t)\left[
    \frac{\sin((q_i-q_k)/2)}
         {\sinh((\gamma_i+\gamma_k)/2)}
